def dfs(graph, start, goal, path=None):
    if path is None: path = [start]
    if start == goal: return path
    for node in graph.get(start, []):
        if node not in path:
            new_path = dfs(graph, node, goal, path + [node])
            if new_path: return new_path
    return None

