# Simple backtracking solver for Map Coloring CSP (Python 3.13+)

def is_valid(var, val, assignment, constraints, neighbors):
    for neighbor in neighbors.get(var, []):
        if neighbor in assignment and assignment[neighbor] == val:
            return False
    return True

def backtrack(assignment, variables, domains, neighbors):
    if len(assignment) == len(variables):
        return assignment

    # Select unassigned variable (simple first-unassigned heuristic)
    unassigned = [v for v in variables if v not in assignment]
    var = unassigned[0]

    for val in domains[var]:
        if is_valid(var, val, assignment, None, neighbors):
            assignment[var] = val
            result = backtrack(assignment, variables, domains, neighbors)
            if result is not None:
                return result
            del assignment[var]
    return None

