import heapq

def a_star(start, goal, adj_list, h):
    pq = [(h[start], 0, start, [start])]
    visited = {}
    while pq:
        f, g, u, path = heapq.heappop(pq)
        if u == goal: return path, g
        if u in visited and visited[u] <= g: continue
        visited[u] = g
        for v, cost in adj_list.get(u, {}).items():
            ng = g + cost
            heapq.heappush(pq, (ng + h[v], ng, v, path + [v]))
    return None, -1

def is_consistent(graph, h):
    for u in graph:
        for v, cost in graph[u].items():
            if h[u] > cost + h[v]:
                return False
    return True

def hill_climbing(func, start, step=0.01, max_iter=1000):
    curr = start
    for _ in range(max_iter):
        next_val = func(curr)
        left, right = func(curr - step), func(curr + step)
        if left >= next_val and left >= right:
            curr -= step
        elif right >= next_val and right >= left:
            curr += step
        else:
            break
    return curr, func(curr)

