import math

def compute_tf(doc):
    tf_dict = {}
    words = doc.split()
    for word in words:
        tf_dict[word] = tf_dict.get(word, 0) + 1
    for word in tf_dict:
        tf_dict[word] = tf_dict[word] / len(words)
    return tf_dict

def compute_idf(corpus):
    import math
    N = len(corpus)
    idf_dict = {}
    all_words = set([word for doc in corpus for word in doc.split()])
    for word in all_words:
        count = sum(1 for doc in corpus if word in doc.split())
        idf_dict[word] = math.log(N / count)
    return idf_dict

