class PatchExtractor(nn.Module):
    def __init__(self, patch_size=16):
        super().__init__()
        self.patch_size = patch_size
    def forward(self, x):
        B, C, H, W = x.shape
        p = self.patch_size
        # x shape: [B, C, H, W] -> [B, num_patches, patch_dim]
        x = x.unfold(2, p, p).unfold(3, p, p)
