def markov_gen(text, length=10):
    words = text.split()
    chain = {}
    for i in range(len(words)-1):
        chain.setdefault(words[i], []).append(words[i+1])

    current = random.choice(list(chain.keys()))
    result = [current]
    for _ in range(length):
        if current in chain:
            current = random.choice(chain[current])
            result.append(current)
        else:
            break
    return ' '.join(result)

